import { cn } from "@/lib/utils";
import { LocationManager } from "@maplibre/maplibre-react-native";
import {
  createContext,
  Fragment,
  use,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type Ref,
} from "react";
import { ActivityIndicator, useColorScheme, View } from "react-native";
import {
  CAPABILITIES,
  createCameraController,
  NativeCamera,
  NativeMap,
  normalizeRegionChangeEvent,
  RENDERER,
  type NativeCameraRef,
  type NativeMapRef,
} from "./map-renderer";
import type { MapInstance, MapProps } from "./map-types";
import { PROVIDERS, resolveStyleUrl } from "@/lib/mapcn/provider";
import { viewportEquals } from "@/lib/mapcn/geo";
import type { MapViewport, PartialViewport } from "@/lib/mapcn/types";

export type { MapProps };
export { CAPABILITIES as MAP_CAPABILITIES };

const MapContext = createContext<MapInstance | null>(null);

/** Accesses the enclosing `Map`'s instance. Throws outside a `Map`. */
function useMap(): MapInstance {
  const context = use(MapContext);
  if (!context) {
    throw new Error("useMap must be used within a Map component");
  }
  return context;
}

/**
 * MapLibre's Map *can* render arbitrary RN children directly (unlike
 * Mapbox's MapView -- see the Mapbox map.tsx for why that one needs a real
 * portal). This context exists anyway, mirroring Mapbox's exactly, so that
 * shared overlay UI (MapControls, MapPopup, and later MapLegend/
 * MapStyleSwitcher) can be a single byte-identical file materialized into
 * both apps instead of special-casing "just render children" here vs
 * "register into a portal" there.
 */
const OverlayContext = createContext<{
  registerOverlay: (id: string, element: ReactNode) => void;
  unregisterOverlay: (id: string) => void;
} | null>(null);

/** Registers/unregisters an RN overlay element rendered on top of the map. Throws outside a `Map`. */
function useOverlay() {
  const context = use(OverlayContext);
  if (!context) {
    throw new Error("useOverlay must be used within a Map component");
  }
  return context;
}

const DEFAULT_VIEWPORT: MapViewport = { center: [0, 0], zoom: 10, bearing: 0, pitch: 0 };
const DEFAULT_VIEWPORT_CHANGE_THROTTLE = 100;

function isLightDarkPair(
  style: NonNullable<MapProps["style"]>,
): style is { light: string | Record<string, unknown>; dark: string | Record<string, unknown> } {
  return typeof style === "object" && ("light" in style || "dark" in style);
}

function resolveMapStyle(
  style: MapProps["style"],
  colorScheme: "light" | "dark",
  provider: (typeof PROVIDERS)[keyof typeof PROVIDERS],
): string | Record<string, unknown> {
  const resolved: string | Record<string, unknown> | undefined = style
    ? isLightDarkPair(style)
      ? style[colorScheme]
      : style
    : undefined;

  if (resolved === undefined) {
    const defaultStyleId = provider.defaultStyle[colorScheme];
    return resolveStyleUrl(provider, defaultStyleId, process.env.EXPO_PUBLIC_MAPTILER_API_KEY);
  }
  if (typeof resolved === "string" && !resolved.includes("://") && !resolved.startsWith("http")) {
    // A bare style id ("streets", "dark", ...) resolved against the provider.
    return resolveStyleUrl(provider, resolved, process.env.EXPO_PUBLIC_MAPTILER_API_KEY);
  }
  return resolved;
}

const DefaultLoader = () => (
  <View className="absolute inset-0 justify-center items-center bg-background/80">
    <ActivityIndicator size="small" color="#999" />
  </View>
);

/** The map container. Renders the native map view, camera, and overlay host. */
function Map({
  children,
  style,
  provider: providerId = "carto",
  colorScheme: colorSchemeProp,
  viewport,
  defaultViewport,
  onViewportChange,
  onViewportChangeEnd,
  viewportChangeThrottle = DEFAULT_VIEWPORT_CHANGE_THROTTLE,
  bounds,
  padding,
  minZoom,
  maxZoom,
  maxBounds,
  interactive = true,
  gestures,
  compass = false,
  logo = false,
  attribution = false,
  scaleBar = false,
  onPress,
  onLongPress,
  onLoad,
  onError: _onError,
  className,
  containerStyle,
  loader,
  ref,
}: MapProps & { ref?: Ref<MapInstance> }) {
  const mapRef = useRef<NativeMapRef | null>(null);
  const cameraRef = useRef<NativeCameraRef | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [overlays, setOverlays] = useState<Record<string, ReactNode>>({});

  const registerOverlay = useCallback((id: string, element: ReactNode) => {
    setOverlays((prev) => ({ ...prev, [id]: element }));
  }, []);

  const unregisterOverlay = useCallback((id: string) => {
    setOverlays((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
  }, []);

  const overlayContextValue = useMemo(() => ({ registerOverlay, unregisterOverlay }), [registerOverlay, unregisterOverlay]);

  const systemColorScheme = useColorScheme();
  const colorScheme: "light" | "dark" = colorSchemeProp ?? (systemColorScheme === "dark" ? "dark" : "light");
  const provider = PROVIDERS[providerId];

  const [styleOverride, setStyleOverride] = useState<string | undefined>(undefined);

  const isControlled = viewport !== undefined;
  const initialViewport: MapViewport = { ...DEFAULT_VIEWPORT, ...defaultViewport, ...viewport };

  // Tracks the last viewport we know the native map is actually showing
  // (from a native event) and the last one we asked it to move to (from a
  // controlled `viewport` prop write). Comparing new values against both,
  // within an epsilon, is what stops onViewportChange -> setState ->
  // viewport prop -> native camera write from ping-ponging forever.
  const lastEmittedRef = useRef<MapViewport>(initialViewport);
  const lastAppliedRef = useRef<MapViewport>(initialViewport);
  const isGestureActiveRef = useRef(false);

  const mapStyle = resolveMapStyle(styleOverride ?? style, colorScheme, provider);

  // createCameraController only stores these ref objects; every `.current`
  // read happens inside the closures it returns, which only ever run from
  // event handlers/effects (see map-renderer.tsx) -- never during render.
  // eslint-disable-next-line react-hooks/refs
  const cameraController = useMemo(() => createCameraController(mapRef, cameraRef), []);

  const instance = useMemo<MapInstance>(
    () => ({
      renderer: RENDERER,
      isLoaded,
      mapRef,
      cameraRef,
      provider: providerId,
      setStyle: setStyleOverride,
      ...cameraController,
    }),
    [isLoaded, cameraController, providerId],
  );

  useImperativeHandle(ref, () => instance, [instance]);

  const throttleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingViewport = useRef<{ viewport: MapViewport; userInteraction: boolean } | null>(null);

  const flushViewportChange = useCallback(() => {
    if (!pendingViewport.current) return;
    const { viewport: next, userInteraction } = pendingViewport.current;
    pendingViewport.current = null;
    lastEmittedRef.current = next;
    onViewportChange?.(next, { userInteraction });
  }, [onViewportChange]);

  const handleRegionIsChanging = useCallback(
    (event: Parameters<typeof normalizeRegionChangeEvent>[0]) => {
      const { viewport: next, userInteraction } = normalizeRegionChangeEvent(event as never);
      isGestureActiveRef.current = userInteraction;
      if (viewportEquals(next, lastAppliedRef.current) || viewportEquals(next, lastEmittedRef.current)) return;

      pendingViewport.current = { viewport: next, userInteraction };
      if (throttleTimer.current) return;
      throttleTimer.current = setTimeout(() => {
        throttleTimer.current = null;
        flushViewportChange();
      }, viewportChangeThrottle);
    },
    [flushViewportChange, viewportChangeThrottle],
  );

  const handleRegionDidChange = useCallback(
    (event: Parameters<typeof normalizeRegionChangeEvent>[0]) => {
      const { viewport: next, userInteraction } = normalizeRegionChangeEvent(event as never);
      isGestureActiveRef.current = false;
      if (throttleTimer.current) {
        clearTimeout(throttleTimer.current);
        throttleTimer.current = null;
      }
      pendingViewport.current = null;
      if (!viewportEquals(next, lastEmittedRef.current)) {
        lastEmittedRef.current = next;
        onViewportChange?.(next, { userInteraction });
      }
      onViewportChangeEnd?.(next, { userInteraction });
    },
    [onViewportChange, onViewportChangeEnd],
  );

  // Controlled mode: push `viewport` prop changes to the native camera,
  // but only when they differ from what we last emitted (echo) and only
  // when no gesture is in progress (never fight a user's finger).
  useEffect(() => {
    if (!isControlled || !isLoaded || isGestureActiveRef.current) return;
    if (viewportEquals(lastEmittedRef.current, viewport as PartialViewport)) return;
    lastAppliedRef.current = { ...lastAppliedRef.current, ...viewport };
    cameraController.setViewport(viewport as PartialViewport, { duration: 300, easing: "ease" });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewport, isControlled, isLoaded]);

  const handleMapIdle = useCallback(() => {
    setIsLoaded(true);
    onLoad?.();
  }, [onLoad]);

  return (
    <MapContext value={instance}>
      <OverlayContext value={overlayContextValue}>
      <View className={cn("flex-1 relative", className)} style={containerStyle}>
        <NativeMap
          ref={mapRef}
          style={{ flex: 1 }}
          // `style` is intentionally typed as `string | Record<string, unknown>`
          // in the shared contract rather than importing MapLibre's
          // StyleSpecification into it (plan §2 D3) -- cast at this boundary.
          mapStyle={mapStyle as never}
          onDidFinishLoadingMap={handleMapIdle}
          onRegionIsChanging={handleRegionIsChanging}
          onRegionDidChange={handleRegionDidChange}
          onPress={onPress ? ((e) => onPress(normalizePress(e))) : undefined}
          onLongPress={onLongPress ? ((e) => onLongPress(normalizePress(e))) : undefined}
          compass={compass !== false}
          compassPosition={typeof compass === "object" ? toOrnamentPosition(compass.position) : undefined}
          logo={logo !== false}
          logoPosition={typeof logo === "object" ? toOrnamentPosition(logo.position) : undefined}
          attribution={attribution !== false}
          attributionPosition={typeof attribution === "object" ? toOrnamentPosition(attribution.position) : undefined}
          scaleBar={scaleBar !== false}
          scaleBarPosition={typeof scaleBar === "object" ? toOrnamentPosition(scaleBar.position) : undefined}
          dragPan={interactive && gestures?.pan !== false}
          touchZoom={interactive && gestures?.zoom !== false}
          touchRotate={interactive && gestures?.rotate !== false}
          touchPitch={interactive && gestures?.pitch !== false}
          contentInset={padding}
        >
          <NativeCamera
            ref={cameraRef}
            initialViewState={{
              center: initialViewport.center,
              zoom: initialViewport.zoom,
              bearing: initialViewport.bearing,
              pitch: initialViewport.pitch,
              ...(bounds ? { bounds } : {}),
            }}
            minZoom={minZoom}
            maxZoom={maxZoom}
            maxBounds={maxBounds}
          />
          {children}
        </NativeMap>
        {loader !== false && !isLoaded && (loader ?? <DefaultLoader />)}
        {Object.entries(overlays).map(([id, element]) => (
          <Fragment key={id}>{element}</Fragment>
        ))}
      </View>
      </OverlayContext>
    </MapContext>
  );
}

Map.displayName = "Map";

function toOrnamentPosition(position?: "top-left" | "top-right" | "bottom-left" | "bottom-right") {
  switch (position) {
    case "top-left":
      return { top: 8, left: 8 };
    case "top-right":
      return { top: 8, right: 8 };
    case "bottom-left":
      return { bottom: 8, left: 8 };
    case "bottom-right":
      return { bottom: 8, right: 8 };
    default:
      return undefined;
  }
}


function normalizePress(event: any) {
  const nativeEvent = event.nativeEvent;
  return {
    coordinate: nativeEvent.lngLat as [number, number],
    point: { x: nativeEvent.point[0], y: nativeEvent.point[1] },
    features: nativeEvent.features ?? [],
  };
}

/** Raw MapLibre permission API -- an escape hatch for cases `useLocationTracking` doesn't cover. */
export { LocationManager };

export { Map, useMap, useOverlay };

/**
 * The MapLibre implementation of the renderer adapter boundary (plan §2 D2).
 *
 * `map.tsx`, `map-marker.tsx` and `map-location-puck.tsx` are the only other
 * files that differ between the MapLibre and Mapbox apps -- everything else
 * (map-geojson, map-cluster-layer, map-heatmap, ...) is written once against
 * this adapter's normalized surface and materialized into both apps
 * unchanged.
 *
 * This file intentionally does NOT re-export a fully-abstracted `<Map>`
 * component: `map.tsx` still writes its own JSX against the native
 * `Map`/`Camera` components below, because the two renderers' props differ
 * enough (see plan §1.2) that a third abstraction layer would just be
 * indirection without reducing real duplication. What *is* shared here is
 * everything that's genuinely renderer-specific but reusable: capability
 * flags, event normalization, and the camera controller that backs
 * `useMap()`.
 */
import {
  Camera,
  GeoJSONSource,
  Layer,
  Map,
  Marker,
  type CameraRef,
  type GeoJSONSourceRef,
  type MapRef,
  type ViewState,
  type ViewStateChangeEvent,
} from "@maplibre/maplibre-react-native";
import type { Feature } from "geojson";
import type { NativeSyntheticEvent } from "react-native";
import { useImperativeHandle, useRef, type ReactElement, type ReactNode, type Ref } from "react";
import type {
  Bounds,
  Coordinate,
  Expression,
  GeoJSONInput,
  MapCameraAnimation,
  MapFeaturePressEvent,
  MapRenderer,
  MapViewport,
} from "@/lib/mapcn/types";
import type { MapInstanceMethods, RendererCapabilities } from "@/components/ui/map-types";
import { bboxOf } from "@/lib/mapcn/geo";

export { Map as NativeMap, Camera as NativeCamera };
export type { CameraRef as NativeCameraRef, MapRef as NativeMapRef };

/**
 * Anchors arbitrary RN content at a geographic coordinate using the
 * renderer's native marker mechanism -- correctness (never drifts during
 * pan/zoom) over a manually re-projected overlay, which is why `MapPopup`
 * (plan §7.10) is built on this instead of `useMap().project()` polling.
 */
export function MapMarkerAnchor({
  id,
  coordinate,
  children,
}: {
  id: string;
  coordinate: Coordinate;
  children: ReactElement;
}) {
  return (
    <Marker id={id} lngLat={coordinate} anchor="bottom">
      {children}
    </Marker>
  );
}

export interface MapSourceProps {
  id: string;
  data: GeoJSONInput;
  children?: ReactNode;
  cluster?: boolean;
  clusterRadius?: number;
  clusterMaxZoom?: number;
  /** MapLibre only -- see CAPABILITIES.clusterMinPoints. */
  clusterMinPoints?: number;
  clusterProperties?: Record<string, unknown>;
  onPress?: (event: NativeSyntheticEvent<unknown>) => void;
  hitbox?: { width: number; height: number };
}

/** Normalized cluster-query surface -- see MapClusterLayer, which is the only consumer of this ref. */
export interface MapSourceRef {
  getClusterExpansionZoom(cluster: Feature): Promise<number>;
  getClusterLeaves(cluster: Feature, limit: number, offset: number): Promise<Array<Feature>>;
}

/** A GeoJSON data source, normalized across renderers -- the foundation MapRoute/MapGeoJSON/MapClusterLayer build on. */
export function MapSource({
  id,
  data,
  children,
  cluster,
  clusterRadius,
  clusterMaxZoom,
  clusterMinPoints,
  clusterProperties,
  onPress,
  hitbox,
  ref,
}: MapSourceProps & { ref?: Ref<MapSourceRef> }) {
  const internalRef = useRef<GeoJSONSourceRef | null>(null);

  useImperativeHandle(
    ref,
    () => ({
      async getClusterExpansionZoom(clusterFeature) {
        const clusterId = clusterFeature.properties?.cluster_id as number | undefined;
        if (clusterId === undefined) throw new Error("[mapcn] getClusterExpansionZoom() called on a non-cluster feature");
        return (await internalRef.current?.getClusterExpansionZoom(clusterId)) ?? 0;
      },
      async getClusterLeaves(clusterFeature, limit, offset) {
        const clusterId = clusterFeature.properties?.cluster_id as number | undefined;
        if (clusterId === undefined) throw new Error("[mapcn] getClusterLeaves() called on a non-cluster feature");
        return (await internalRef.current?.getClusterLeaves(clusterId, limit, offset)) ?? [];
      },
    }),
    [],
  );

  return (
    <GeoJSONSource
      ref={internalRef}
      id={id}
      data={data as never}
      cluster={cluster}
      clusterRadius={clusterRadius}
      clusterMaxZoom={clusterMaxZoom}
      clusterMinPoints={clusterMinPoints}
      clusterProperties={clusterProperties as never}
      onPress={onPress as never}
      // MapLibre's hitbox is edge padding; Mapbox's is a width/height box.
      // The shared contract uses Mapbox's simpler shape (plan §2 D3) and
      // this adapter converts it to symmetric padding.
      hitbox={hitbox ? { top: hitbox.height / 2, bottom: hitbox.height / 2, left: hitbox.width / 2, right: hitbox.width / 2 } : undefined}
    >
      {children}
    </GeoJSONSource>
  );
}

export type MapLayerType = "fill" | "line" | "circle" | "symbol" | "heatmap";

export interface MapLayerProps {
  id: string;
  type: MapLayerType;
  style?: Record<string, unknown>;
  filter?: Expression;
  beforeId?: string;
  minZoom?: number;
  maxZoom?: number;
  /**
   * Injected by GeoJSONSource's automatic source-id cloning
   * (`cloneReactChildrenWithProps` in @maplibre/maplibre-react-native) --
   * it targets MapLayer directly since that's the actual JSX child, so this
   * must be declared and forwarded to `<Layer source={...} />`, or every
   * layer falls back to the native `MLRNSource.insertReactSubview:`/
   * `addToMap` fallback that infers `sourceID` from view-mount order --
   * which races with `MLRNMapView`'s `didFinishLoadingStyle:` on first
   * mount and throws "Cannot find source with id" until a JS reload masks
   * it via a stale view being reused.
   */
  source?: string;
}

export function MapLayer({ id, type, style, filter, beforeId, minZoom, maxZoom, source }: MapLayerProps) {
  return (
    <Layer
      id={id}
      source={source}
      type={type}
      style={style as never}
      filter={filter as never}
      beforeId={beforeId}
      minzoom={minZoom}
      maxzoom={maxZoom}
    />
  );
}

export const RENDERER: MapRenderer = "maplibre";

export const CAPABILITIES: RendererCapabilities = {
  clusterMinPoints: true,
  locationPuckPulsing: false,
  locationPuckScale: false,
  locationPuckImages: false,
  locationPuckPress: true,
  locationPuckCustomChildren: true,
};

export function normalizeViewport(viewState: ViewState): MapViewport {
  return {
    center: viewState.center,
    zoom: viewState.zoom,
    bearing: viewState.bearing,
    pitch: viewState.pitch,
  };
}

export function normalizeRegionChangeEvent(
  event: NativeSyntheticEvent<ViewStateChangeEvent>,
): { viewport: MapViewport; userInteraction: boolean } {
  const { animated: _animated, userInteraction, ...viewState } = event.nativeEvent;
  return { viewport: normalizeViewport(viewState), userInteraction };
}

interface RawPressEvent {
  lngLat: Coordinate;
  point: [number, number];
  features?: Array<unknown>;
}

export function normalizeFeaturePress(event: NativeSyntheticEvent<RawPressEvent>): MapFeaturePressEvent {
  const { lngLat, point, features } = event.nativeEvent;
  return {
    coordinate: lngLat,
    point: { x: point[0], y: point[1] },

    features: (features as Array<any> | undefined) ?? [],
  };
}

function mapEasing(easing: MapCameraAnimation["easing"]): "linear" | "ease" | "fly" | undefined {
  return easing;
}

/**
 * Builds the camera-facing subset of `MapInstance` on top of MapLibre's
 * native `MapRef`/`CameraRef`. `map.tsx` combines this with `isLoaded`,
 * `renderer` and the raw refs to produce the full instance handed out by
 * `useMap()`.
 */
export function createCameraController(
  mapRef: { current: MapRef | null },
  cameraRef: { current: CameraRef | null },
): MapInstanceMethods {
  return {
    async getViewport() {
      const viewState = await mapRef.current?.getViewState();
      if (!viewState) throw new Error("[mapcn] getViewport() called before the map finished loading");
      return normalizeViewport(viewState);
    },

    setViewport(viewport, animation) {
      const duration = animation?.duration ?? 0;
      const options = {
        center: viewport.center,
        zoom: viewport.zoom,
        bearing: viewport.bearing,
        pitch: viewport.pitch,
        padding: animation?.padding,
      };
      if (duration > 0 && viewport.center) {
        cameraRef.current?.easeTo({ ...options, center: viewport.center, duration, easing: mapEasing(animation?.easing) });
      } else if (viewport.center) {
        cameraRef.current?.jumpTo({ ...options, center: viewport.center });
      } else {
        // No center change -- easeTo also accepts a center-less stop via setStop.
        cameraRef.current?.setStop({ ...options, duration, easing: mapEasing(animation?.easing) });
      }
    },

    flyTo(center, options) {
      cameraRef.current?.flyTo({
        center,
        zoom: options?.zoom,
        duration: options?.duration ?? 1000,
        easing: mapEasing(options?.easing) ?? "fly",
        padding: options?.padding,
      });
    },

    moveTo(center, options) {
      const duration = options?.duration ?? 0;
      if (duration > 0) {
        cameraRef.current?.easeTo({
          center,
          zoom: options?.zoom,
          duration,
          easing: mapEasing(options?.easing),
          padding: options?.padding,
        });
      } else {
        cameraRef.current?.jumpTo({ center, zoom: options?.zoom, padding: options?.padding });
      }
    },

    zoomTo(zoom, options) {
      cameraRef.current?.zoomTo(zoom, {
        duration: options?.duration,
        easing: mapEasing(options?.easing),
        padding: options?.padding,
      });
    },

    async zoomBy(delta, options) {
      const currentZoom = (await mapRef.current?.getZoom()) ?? 0;
      cameraRef.current?.zoomTo(currentZoom + delta, {
        duration: options?.duration,
        easing: mapEasing(options?.easing),
        padding: options?.padding,
      });
    },

    fitBounds(bounds, options) {
      cameraRef.current?.fitBounds(bounds, {
        duration: options?.duration,
        easing: mapEasing(options?.easing),
        padding: options?.padding,
      });
    },

    fitFeatures(data, options) {
      const bbox = bboxOf(data);
      cameraRef.current?.fitBounds(bbox, {
        duration: options?.duration,
        easing: mapEasing(options?.easing),
        padding: options?.padding,
      });
    },

    resetNorth(options) {
      // setStop (not easeTo) accepts a center-less stop.
      cameraRef.current?.setStop({
        bearing: 0,
        duration: options?.duration ?? 300,
        easing: mapEasing(options?.easing),
      });
    },

    async project(coordinate) {
      const point = await mapRef.current?.project(coordinate);
      if (!point) throw new Error("[mapcn] project() called before the map finished loading");
      return { x: point[0], y: point[1] };
    },

    async unproject(point) {
      const coordinate = await mapRef.current?.unproject([point.x, point.y]);
      if (!coordinate) throw new Error("[mapcn] unproject() called before the map finished loading");
      return coordinate;
    },

    async queryFeatures(options) {
      // `Expression`/filter is intentionally loosely typed in the shared
      // contract (plan §7.0) to match both renderers' style-spec grammar;
      // MapLibre's own FilterSpecification union is far stricter, so the
      // cast happens right at this adapter boundary, not in the public API.
      const queryOptions = {
        layers: options?.layers,
        filter: options?.filter as never,
      };

      if (options?.point) {
        return (
          (await mapRef.current?.queryRenderedFeatures([options.point.x, options.point.y], queryOptions)) ?? []
        );
      }

      if (options?.bounds) {
        // MapRef.queryRenderedFeatures takes *pixel* bounds, not geographic
        // ones, so the geographic Bounds get projected to screen space first.
        const [west, south, east, north] = options.bounds as Bounds;
        const topLeft = await mapRef.current?.project([west, north]);
        const bottomRight = await mapRef.current?.project([east, south]);
        if (!topLeft || !bottomRight) return [];
        return (await mapRef.current?.queryRenderedFeatures([topLeft, bottomRight], queryOptions)) ?? [];
      }

      return (await mapRef.current?.queryRenderedFeatures(queryOptions)) ?? [];
    },
  };
}
